def format_bytes(n):
    """Convert bytes to a human-readable string (e.g., '1.5 KB')."""
    if n < 0:
        raise ValueError("n must be non-negative")
    for unit in ['B', 'KB', 'MB', 'GB', 'TB']:
        if n < 1024.0:
            return f"{n:.1f} {unit}"
        n /= 1024
    return f"{n:.1f} PB"'
